mapper.select:
select ol.*, e.name as operatorName from operation_log ol left join employee e on ol.operator_id = e.id
and ol.description like concat('%',#{description},'%')
and ( ol.description like concat('%',#{keyword},'%') or e.name like concat('%',#{keyword},'%') or ol.request_uri like concat('%',#{keyword},'%') or ol.client_ip like concat('%',#{keyword},'%') )
and ol.operator_id = #{operatorId}
and ol.request_method = #{requestMethod}
order by ol.create_time desc

select ol.id, ol.description, ol.operator_id, ol.request_method, ol.request_uri,
       ol.cost_time, ol.create_time, e.name as operator_name
from operation_log ol left join employee e on ol.operator_id = e.id

    ol.id > #{lastId} and ol.id <= #{snapshot.maxId}
    and ol.description like concat('%',#{snapshot.description},'%')

        and (ol.description like concat('%',#{snapshot.keyword},'%') or e.name like concat('%',#{snapshot.keyword},'%')
            or ol.request_uri like concat('%',#{snapshot.keyword},'%'))

    and ol.operator_id = #{snapshot.operatorId}
    and ol.request_method = #{snapshot.requestMethod}
    and ol.create_time >= #{snapshot.startTime}
    and ol.create_time <= #{snapshot.endTime}

order by ol.id
limit #{limit}
